import Ajv from "ajv";
import type { ExecutorResult } from "./types.js";

const ajv = new Ajv({ allErrors: true });

export const resultJsonSchema = {
  $schema: "http://json-schema.org/draft-07/schema#",
  title: "ExecutorResult",
  description: "The JSON payload an executor writes to resultPath on completion.",
  type: "object",
  required: ["terminal_status"],
  additionalProperties: false,
  properties: {
    terminal_status: {
      type: "string",
      enum: ["in_review", "blocked", "failed"],
    },
    token_usage: {
      type: "object",
      required: ["input", "output"],
      additionalProperties: false,
      properties: {
        input: { type: "integer", minimum: 0 },
        output: { type: "integer", minimum: 0 },
      },
    },
    blocked_reason: { type: "string", minLength: 1 },
    blocked_suggestion: { type: "string", minLength: 1 },
  },
  if: {
    properties: { terminal_status: { const: "blocked" } },
    required: ["terminal_status"],
  },
  then: {
    required: ["terminal_status", "blocked_reason"],
  },
} as const;

const _validateFn = ajv.compile(resultJsonSchema);

export interface ValidationError {
  message: string;
  path: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

/**
 * Validate an executor result.json payload against the ABI schema.
 * Schema violations must be mapped by the orchestrator to
 * terminal_status: "failed", blocked_reason: "result_schema_invalid".
 */
export function validateResult(data: unknown): ValidationResult {
  const valid = _validateFn(data);
  if (valid) {
    return { valid: true, errors: [] };
  }
  const errors: ValidationError[] = (_validateFn.errors ?? []).map((e) => ({
    message: e.message ?? "unknown validation error",
    path: e.instancePath || "/",
  }));
  return { valid: false, errors };
}

/**
 * Type guard: returns true and narrows data to ExecutorResult when the
 * schema validates.
 */
export function isValidResult(data: unknown): data is ExecutorResult {
  return validateResult(data).valid;
}

