import type { ExecutorAdapter, ExecutorInput, ExecutorResult } from "./types.js";

/**
 * A no-I/O ExecutorAdapter used by orchestrator tests.
 * The factory accepts a fixed result (or a factory function) and returns
 * an adapter that resolves immediately with that result — no spawning,
 * no file I/O, no side effects.
 */
export function createFakeAdapter(
  result: ExecutorResult | (() => ExecutorResult),
): ExecutorAdapter {
  return {
    async run(_input: ExecutorInput): Promise<ExecutorResult> {
      return typeof result === "function" ? result() : result;
    },
  };
}

/**
 * Convenience: a FakeAdapter that always reports in_review.
 */
export function createInReviewAdapter(): ExecutorAdapter {
  return createFakeAdapter({ terminal_status: "in_review" });
}

/**
 * Convenience: a FakeAdapter that always reports blocked.
 */
export function createBlockedAdapter(
  blocked_reason: string,
  blocked_suggestion?: string,
): ExecutorAdapter {
  return createFakeAdapter({
    terminal_status: "blocked",
    blocked_reason,
    blocked_suggestion,
  });
}

/**
 * Convenience: a FakeAdapter that always reports failed.
 */
export function createFailedAdapter(): ExecutorAdapter {
  return createFakeAdapter({ terminal_status: "failed" });
}

