import { describe, it, expect } from "vitest";
import { validateResult, isValidResult } from "../src/schema.js";

describe("validateResult", () => {
  it("accepts a valid in_review result", () => {
    const result = validateResult({ terminal_status: "in_review" });
    expect(result.valid).toBe(true);
    expect(result.errors).toHaveLength(0);
  });

  it("accepts an in_review result with optional token_usage", () => {
    const result = validateResult({
      terminal_status: "in_review",
      token_usage: { input: 1000, output: 500 },
    });
    expect(result.valid).toBe(true);
  });

  it("accepts a valid blocked result with reason and suggestion", () => {
    const result = validateResult({
      terminal_status: "blocked",
      blocked_reason: "missing_tool",
      blocked_suggestion: "Install the required tool and retry.",
    });
    expect(result.valid).toBe(true);
  });

  it("accepts a valid blocked result with reason and without suggestion", () => {
    const result = validateResult({
      terminal_status: "blocked",
      blocked_reason: "missing_tool",
    });
    expect(result.valid).toBe(true);
  });

  it("accepts a valid failed result", () => {
    const result = validateResult({ terminal_status: "failed" });
    expect(result.valid).toBe(true);
  });

  it("rejects a blocked result missing blocked_reason", () => {
    const result = validateResult({ terminal_status: "blocked" });
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBeGreaterThan(0);
  });

  it("rejects an unknown terminal_status", () => {
    const result = validateResult({ terminal_status: "unknown_value" });
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBeGreaterThan(0);
  });

  it("rejects a result with missing terminal_status", () => {
    const result = validateResult({});
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBeGreaterThan(0);
  });

  it("rejects a result with additional unknown properties", () => {
    const result = validateResult({
      terminal_status: "in_review",
      unexpected_field: "oops",
    });
    expect(result.valid).toBe(false);
  });
});

describe("isValidResult", () => {
  it("returns true for a valid in_review result and narrows the type", () => {
    const data: unknown = { terminal_status: "in_review" };
    expect(isValidResult(data)).toBe(true);
    if (isValidResult(data)) {
      expect(data.terminal_status).toBe("in_review");
    }
  });

  it("returns false for an invalid result", () => {
    expect(isValidResult({ terminal_status: "blocked" })).toBe(false);
  });
});

